alter table engagement_sends add column message_sids text[];

comment on column engagement_sends.message_sids is 'Twilio message SIDs for every message sendRcsTurn produced for this engagement turn (a turn is prose + card(s) + chips, so this is often more than one SID) — captured from twilioClient.js#sendRcsTurn''s return value at send time in lib/engagementSend.js#sendAndLogEngagement. Null/empty for suppressed rows or the credential-less no-op path. Lets a later query join against message_delivery_status (by unnesting this array) to answer "what was the actual carrier delivery outcome for sends of this slot/archetype" — the per-slot deliverability metric the engagement design doc calls for, distinct from and downstream of this table''s own status column (which only reflects the synchronous send-API-call outcome).';
